"""32 original mock interview drills with model answers; not personal stories or company claims."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
DRILLS=[]
def add(section,title,scenario,answers,followups,code=None,lab=None):
 DRILLS.append(dict(section=section,title=title,scenario=scenario,answers=answers,followups=followups,code=code,lab=lab))

def coding_drills():
 problems=json.loads((ROOT/'data/leetcode.json').read_text(encoding='utf-8'))
 specs=[('LC001','Two Sum and its variants'),('LC018','Merge overlapping intervals'),('LC011','Validate balanced parentheses'),(None,'LRU Cache from scratch'),('LC005','Top K frequent elements'),(None,'Detect a cycle in a linked list'),('LC017','Number of islands'),('LC009','Best time to buy and sell stock')]
 for pid,title in specs:
  if pid:
   p=next(p for p in problems if p['id']==pid)
   answers=[('Clarify and solve',p['problem']+' '+p['constraints']),('Brute force',p['bruteForce']+' Time '+p['bruteTime']+'; space '+p['bruteSpace']+'.'),('Improved solution and invariant',p['approach']+' '+p['walkthrough']+' Time '+p['time']+'; space '+p['space']+'.'),('Boundary cases',p['edgeCases'])]
   if pid=='LC001':answers.append(('Variants are different contracts','One pair of indices uses a complement map; sorted input permits two pointers. For unique value pairs, sort a copy and skip duplicate endpoint values after a match. Counting index pairs instead accumulates prior complement frequency: [1,1,1,1] with target 2 has six index pairs but one unique value pair. Use widened arithmetic for sums/complements. The runnable MockCodingDemo implements all four; a request for all output pairs may require quadratic output size.'))
   add('DSA / Coding',title,p['example'],answers,['State the invariant without looking at code.','Give an adversarial input, not just the supplied sample.'],p['code'],'examples/mock/MockCodingDemo.java' if pid=='LC001' else None)
   DRILLS[-1]['problemId']=pid
  elif title.startswith('LRU'):
   add('DSA / Coding',title,'Capacity two: put(1,A), put(2,B), get(1), put(3,C). Key 2 must be evicted.',[
    ('State and invariant','Use HashMap<K,Node> plus a doubly linked recency list. Every real list node must have one map entry and matching forward/back links. Head is newest and tail is oldest; sentinels handle empty/single-entry boundaries.'),('Operations','get misses without mutation or detaches/moves the found node to newest. put updates and refreshes an existing node; a new entry beyond capacity evicts the tail node from both list and map. Define zero capacity and null behavior explicitly.'),('Complexity and safety','List work is O(1); hash-table operations are expected/amortized O(1), not a deterministic guarantee under arbitrary collisions. Space is O(capacity). A successful get changes order, so synchronize it with writes for an exact shared local LRU.'),('Solution and tests','The linked runnable LruCacheDemo includes explicit nodes rather than delegating the implementation to LinkedHashMap. It tests update recency, zero capacity, list/map invariants and 1,000 deterministic operations against an independent access-ordered reference model.')],['Why does get need synchronization?','What changes if values expire independently of recency?'],(ROOT/'examples/lld/LruCacheDemo.java').read_text(encoding='utf-8'),'examples/lld/LruCacheDemo.java')
  else:
   code='''static class Node {int value; Node next;}
static Node cycleEntry(Node head) {
 Node slow=head, fast=head;
 while(fast!=null && fast.next!=null) {
  slow=slow.next; fast=fast.next.next;
  if(slow==fast) {
   Node start=head;
   while(start!=slow) {start=start.next; slow=slow.next;}
   return start;
  }
 }
 return null;
}'''
   add('DSA / Coding',title,'Nodes A → B → C → B have cycle entry B. Equal node values alone do not mean a cycle.',[
    ('Brute force','Walk the nodes while storing object identities in a set. A repeated node reference reveals the cycle; null ends an acyclic list. Time O(n), extra space O(n). Use reference identity rather than value equality.'),('Floyd solution','Advance slow by one and fast by two. In a finite cycle their relative distance moves by one modulo cycle length and eventually becomes zero. Stop only after checking fast and fast.next for null.'),('Find the entry','After a meeting, start one pointer at head and advance both by one until they meet at the entry. If the prefix length is mu and cycle length lambda, the meeting-distance relation implies mu steps align their cycle positions. Detection plus entry recovery is O(n) time and O(1) extra space.'),('Adversarial tests','Test null, one node with null next, self-loop, a cycle beginning at head, a nonempty prefix, and distinct nodes with equal values. Never modify next links merely to mark visited nodes.')],['Prove why the pointers meet inside a cycle.','How would you calculate the cycle length?'],code,'examples/mock/MockCodingDemo.java')

coding_drills()
add('Low-Level Design','Design an ATM','Alice withdraws 600 units from notes {500:1, 200:3}; greedy 500 first cannot finish, but three 200 notes can.',[
 ('Clarify operations and trust','Separate session authentication, account permission, cash inventory, withdrawal orchestration and hardware adapter. The ATM/controller verifies card/PIN through an appropriate secure banking integration; the lab does not handle real PINs or card data. Derive trusted identity at that boundary rather than treating a passed user string as proof.'),
 ('Domain and transitions','Model Account/Balance, CashInventory, Withdrawal(requestKey, amount, state) and Dispenser. A real state machine can progress AUTHORIZED → CASH_RESERVED → DISPENSE_REQUESTED → DISPENSED or an explicit UNKNOWN/REVERSED path. Enforce positive amount, limits, funds and an exact feasible denomination plan before decrementing anything.'),
 ('Implement the local decision','The Java lab uses bounded-note backtracking because a greedy choice can fail for available denominations. Under one local lock it checks owner, idempotency key/payload and balance, finds a plan, then updates balance and inventory together. A duplicate key returns the prior result; a mismatched amount is rejected.'),
 ('Do not confuse local atomicity with dispensing','A physical dispense can succeed while its reply is lost. Persist a durable operation journal and reconcile device counters/sensor events; do not blindly debit again or instantly reverse while the cash outcome is unknown. A database transaction cannot atomically roll back cash already handed out. Network-bank authorization and local cash reservation need a recovery protocol.'),
 ('Solution limits and tests','AtmDemo simulates only the local logical decision; it does not operate hardware, persist a ledger or implement banking compliance. It tests non-greedy exact notes, replay, unauthorized subject, conflicting key and no-change failure. Backtracking is exponential in denomination/count choices; bound withdrawal sizes and select an appropriate bounded-change algorithm for a real configuration.')],['What if cash was dispensed but the confirmation was lost?','How do two ATMs coordinate one account’s available funds?'],(ROOT/'examples/mock/AtmDemo.java').read_text(encoding='utf-8'),'examples/mock/AtmDemo.java')
add('Low-Level Design','Design a stock order book','S1 sells five units at 100; S2 sells three at 100. B1 buys six with limit 101: fill S1 first for five and S2 for one, at maker price 100.',[
 ('Specify the market contract','This exercise is one instrument, integer price ticks, positive quantities and limit orders with price-time priority. State whether matching uses maker price, how cancellation works and whether market orders/self-trade prevention/auctions exist. The lab deliberately omits those extra market rules.'),
 ('Data structures','Maintain a buy priority queue ordered by highest price then server sequence and a sell queue ordered by lowest price then sequence. Orders carry stable IDs, immutable original request and mutable remaining quantity. An active-ID map supports cancellation; cancelled heap nodes are lazily skipped. A production price-level book may use ordered price maps plus FIFO queues.'),
 ('Matching operation','A sequenced submit repeatedly inspects the best opposite order, verifies crossing prices and trades min(takerRemaining,makerRemaining). Update both remaining quantities, remove a finished maker and rest the taker only if quantity remains. Do not reorder same-price makers by client timestamps. The lab serializes commands with synchronized and uses server sequence numbers.'),
 ('Retries and cancellation','Retain request/result identity so retrying the exact original order ID returns its original submission result without rematching. Reusing the ID with changed parameters conflicts. A cancel applies to the currently resting remainder once; it cannot erase an executed trade. In a real service authenticate clients, bind order ownership and authorize cancellation.'),
 ('Recovery and cost','The runnable lab tests maker price, same-price FIFO, partial fills, replay, cancellation and payload conflict. It is in-memory, uses lazy tombstones and keeps deduplication history indefinitely, so it is not a production exchange. Journal accepted commands with deterministic sequencing, snapshots/replay and retention in a real design. For t matches, heap work is roughly O((t+1) log n), plus lazy cleanup; cancellation marks O(1) but memory cleanup is deferred.')],['Which state wins when cancel and execution race?','Why can a retry not simply submit a new order ID?'],(ROOT/'examples/mock/OrderBookDemo.java').read_text(encoding='utf-8'),'examples/mock/OrderBookDemo.java')
add('Low-Level Design','Design a parking lot','Two entry gates compete for one free car slot.',[
 ('Model answer','Define immutable Vehicle/Slot/Gate/Ticket values and one authoritative lot allocator. Select a documented compatibility/nearest-level policy, then assign slot and record active ticket atomically. Exit validates an active ticket and exit gate before freeing the exact slot once.'),('Concurrency and recovery','A synchronized local allocator is enough only for one process. Multiple replicas need a transaction/constraint or a single assignment owner. Persist admissions and reconcile sensors for restart recovery. Keep payment/hardware I/O outside a coarse slot lock.'),('Worked solution','The full ParkingLotDemo and tutorial cover levels, entry/exit directions, duplicate plates, closed tickets and two concurrent entry attempts. State which errors leave occupancy unchanged and which operations are intentionally outside the demo.')],['How would you change the slot-selection policy without changing ticket lifecycle?'],None,'examples/lld/ParkingLotDemo.java')
add('Low-Level Design','Design a rate limiter class','One tenant has one token left and two request threads arrive together.',[
 ('Model answer','Bucket owns capacity, fractional tokens, refill rate, last time and injected monotonic clock. Refill, compare and consume must happen inside one atomic boundary. Limiter selects a configured bucket using trusted caller/tenant identity.'),('Error behavior and scale','Reject invalid cost/unknown tenant; deny without enough tokens. A controller translates deny to 429 with retry guidance. Independent process-local buckets multiply the effective global limit; use one key owner/shared atomic operation or explicitly allocated local budgets across servers.'),('Worked solution','TokenBucketDemo tests refill with an injected clock instead of sleeps, burst capacity and 50 competing calls for ten tokens. It explains outage policy, tenant memory bounds and why rate limiting does not replace in-flight backpressure.')],['What happens to quota when an idle bucket is evicted and recreated?'],None,'examples/lld/TokenBucketDemo.java')
add('System Design','Design payment processing with idempotent transfers','Alice requests transfer T81 of 5,000 paise from authorized account A to account B; the client loses the response after commit.',[
 ('Begin with invariants and ownership','Clarify whether this is an internal same-ledger transfer or an external rail. For a same-currency internal transfer, accepted postings must balance, the caller may debit only authorized accounts, and one logical request must not create duplicate postings. Represent currency explicitly and use bounded integer minor units or an appropriate decimal money type, never binary floating-point for ledger amounts.'),
 ('API and data contract','POST /transfers carries source, destination, amount, currency and a stable idempotency key. Derive actor/tenant from verified credentials, verify debit permission and limits, and bind the key to the operation’s payload fingerprint. Store Transfer, immutable balanced Posting records, account concurrency state and an outbox event. Retain idempotency results under a documented policy.'),
 ('Follow the local transaction','Claim the scoped key under a unique constraint. Lock/serialize affected account state in a consistent order or use an equivalent guarded transactional design, validate available funds, write balanced postings and update the chosen balance projection with the transfer/result/outbox in one transaction. Retry serialization/deadlock failures within bounds using the same logical identity. A pre-transaction balance read is not sufficient.'),
 ('Handle the lost response','If commit succeeded, retrying T81 returns the recorded result. Concurrent same-key calls must not both execute the transfer. A different payload with the same key conflicts. If outcome is unknown after timeout, query by operation identity; do not create a fresh key and assume failure.'),
 ('External rails need another protocol','A remote bank/provider cannot share an ordinary local database commit. Record a pending instruction, deliver through a recoverable outbox/worker, use a stable provider reference and reconcile authenticated confirmations and statement data. Model PENDING/UNKNOWN/CONFIRMED/FAILED explicitly; reversals are new recorded postings, not deletion of history. A webhook or browser return URL alone is not sufficient evidence without its authenticity/state checks.'),
 ('Observe and test','Test simultaneous retries, competing debits, insufficient funds, crash before/after commit, lost provider acknowledgement and duplicate/out-of-order confirmations. Reconcile ledger versus balance projections and external statements. Monitor unbalanced journals, pending age, duplicate conflicts and reconciliation breaks. Scaling the service must preserve one authoritative account/transfer decision boundary; sharding adds cross-boundary coordination, not free atomicity.')],['What does successful mean for an internal versus external transfer?','How do you avoid deadlock when two transfers involve the same accounts in reverse order?'])
add('System Design','Design a real-time fraud detection pipeline','Transfer T81 reaches authorization while device and velocity signals may be stale; a decision must arrive within a bounded deadline.',[
 ('Define decision responsibility','Separate fast authorization-time risk decision from asynchronous investigation/retraining. Decide which events require block, step-up, hold or a documented fallback; availability of a model is not permission to approve every unknown transfer. A risk score is evidence for a policy decision, not an authenticated instruction to move money.'),
 ('Ingest trusted events','Record stable event ID, tenant/account scope, event and ingestion times, schema version and relevant verified signals. Authenticate producer workloads and minimize sensitive data. Stream ingestion must tolerate retries and out-of-order delivery. A transactional source outbox prevents a fraud event representing a transfer that never committed where the flow requires committed events.'),
 ('Build and read features','A stream processor updates windowed velocity/device/account features with explicit late-event and deduplication rules. The decision service reads a versioned feature snapshot, records feature freshness and calls a bounded rules/model evaluation. Keep event-time versus processing-time semantics visible; replaying an event must not double the velocity count.'),
 ('Make a bounded, auditable decision','Within the endpoint deadline, combine deterministic rules, model/version, available features and policy version into an allow/block/step-up/hold result. Store reason codes and input evidence references that explain the actual decision; do not fabricate a human-readable justification after the fact. Human review and customer-facing messaging have separate access and privacy requirements.'),
 ('Failures, safety and drift','If model/feature access times out, choose a preapproved conservative rules path, hold/step-up or unavailable result depending on transaction risk. Mark missing/stale features rather than substituting zero silently. Monitor false-positive rates, confirmed fraud, feature lag, model calibration and cohort performance. Delayed labels and adversarial behavior complicate evaluation; raw approval rate alone is insufficient.'),
 ('Validation and scale','Replay fixed historical/test event sequences with deduplication, late data and stale features. Test endpoint deadlines, tenant isolation, replay determinism for recorded versions and malformed producer events. Partition feature updates by a key appropriate to the rule, recognizing that cross-account/device aggregation may require another stage. Keep an asynchronous investigation/retraining pipeline from becoming a synchronous dependency for every transfer.')],['What happens if a velocity feature is ten minutes stale?','Which decision artifacts let an investigator reproduce the applied policy?'])
add('System Design','Design trade settlement and reconciliation','An executed trade requires cash/securities obligations; one settlement confirmation arrives twice and a statement arrives late.',[
 ('Separate execution from settlement','An order-book fill is not proof assets and cash have settled. Record executed trade identity and contractual obligations, relevant parties, instrument/currency, amounts, lifecycle and business-date/calendar semantics. Settlement timing and rules vary by market; clarify them rather than assume one global schedule.'),
 ('Create durable obligations','Consume authenticated execution events with stable trade IDs; deduplicate and validate them, create versioned obligations and outbox instructions transactionally. Apply reference data and configured calendars/cutoffs using explicit time zones. Keep amendments/cancellations as versioned events with allowed transitions instead of overwriting the original evidence.'),
 ('Process external instructions','Workers submit instructions to the chosen custodian/clearing/settlement infrastructure with stable references. Authenticate and deduplicate confirmations. Model pending, matched, settled, failed and unknown states according to that rail’s contract. A timeout is not proof of rejection; reconcile before resending in a way that could duplicate settlement.'),
 ('Reconcile three views','Compare internal trade/obligation/ledger state, external confirmations and authoritative statements/positions using declared identifiers, amounts, currency, value date and version. Classify missing, duplicate, quantity/amount and timing breaks. Do not fuzzy-match ambiguous records into an automatic clean status merely to make totals agree.'),
 ('Resolve breaks with controls','Create a durable case with evidence and assigned owner. Automated safe retries and authorized manual repair require explicit policy, audit and appropriate separation of duties. Use adjustment/reversal records rather than deleting history. Late statements should update reconciliation state idempotently and may reopen a previously provisional comparison.'),
 ('Test recovery and reporting','Test duplicate instructions/confirmations, partial settlement where supported, calendar boundaries, late files, mismatched currency, ambiguous matches and restart during a batch. Version input files and reconciliation rules; checkpoint progress with sink idempotency. Report pending age, unreconciled exposure and break counts without labeling a matched instruction as finally settled unless the evidence supports it.')],['How is a trade marked settled if one confirmation is missing?','Why can two matching aggregate totals still conceal individual reconciliation breaks?'])
add('System Design','Design an audit log that cannot be tampered with','A privileged operator tries to modify or delete an earlier payment event and conceal that change.',[
 ('Challenge the absolute guarantee','Define the attacker and trust boundaries. No ordinary application table is absolutely tamper-proof against every administrator and compromised key. Aim for append-only access controls, independently verifiable tamper evidence, protected retention and monitored custody. Explain exactly which principals and failure modes the design resists.'),
 ('Record structured facts','Capture stable event ID, actor/workload identity, tenant, action, target, before/after references where appropriate, outcome, correlation ID, timestamp and schema/version. Avoid copying secrets or unnecessary personal data. Bind business-state changes and audit intent using a transactional outbox where possible; audit omissions also matter.'),
 ('Make modification detectable','An ordered stream can hash each canonically encoded event with the prior hash and sequence. Sign/anchor checkpoints in an independently controlled destination so rewriting an entire local chain or truncating its tail is detectable. Protect signing keys, rotate with verification metadata and define clock/ordering semantics. A hash chain alone does not stop an attacker who can rewrite all records and all anchors.'),
 ('Protect retention and access','Write protected object versions to an appropriate WORM/retention store with separate writer, reader and retention-administration privileges. Choose retention/hold rules with the responsible compliance team. For example, object-lock protections apply to specified object versions; a new object version/delete marker does not mean the protected version changed. Governance versus stricter retention modes have different bypass behavior.'),
 ('Verify and investigate','Run independent sequence/checkpoint/hash/signature verification, alert on gaps and failed writes, and keep redundant custody/backups. Auditors query an authorized index while verifying evidence against the protected source; rebuilding a search index must not rewrite original history. Access to the audit service itself is audited through a separate appropriate boundary.'),
 ('Failure and acceptance tests','Test attempted overwrite/delete, missing sequence, altered payload, chain rewrite without anchor authority, truncated tail, key rotation, clock anomalies and an unavailable archive. Decide which sensitive business operations must fail or durably buffer if required audit capture cannot be guaranteed. Do not return compliance assurances based solely on using a named storage product.')],['How would you detect an attacker deleting the newest 100 events?','What if the application and its signing key are both compromised?'])
add('Java / Spring','HashMap internals and what changed in Java 8','Many distinct keys collide in one bucket, and a mutable key is changed after insertion.',[
 ('Lookup mechanics','A HashMap uses hash spreading to choose a bucket, then checks hash and equals among entries. Equal keys must have equal hashCode; unequal keys may collide. Power-of-two table capacity allows a bit-mask index. Resizing redistributes bins as capacity grows; default load factor is a sizing policy, not a guarantee of constant latency.'),
 ('Java 8 change','OpenJDK HashMap can convert a heavily populated collision bin into a balanced tree when thresholds and minimum table capacity permit. Common OpenJDK constants are treeify threshold 8 and minimum table capacity 64; below that it may resize rather than treeify. These are implementation details, not a universal Map contract. Tree-bin tie breaking/comparability details matter; do not promise identical asymptotic guarantees for every pathological key type.'),
 ('Practical mistakes','Changing fields used by equals/hashCode after insertion can make lookup fail even though iteration still shows the entry. HashMap is not thread-safe; fail-fast iteration is best effort, not a concurrency control. Null handling differs from ConcurrentHashMap. To safely accumulate concurrently, use documented atomic concurrent-map operations rather than synchronized-looking combinations of get and put.'),
 ('Explain and test','Demonstrate two equal key instances retrieving one mapping, distinct colliding keys retaining separate values, resizing with stable keys and a mutable-key lookup failure. Explain expected/amortized behavior and why poorly distributed hashes and unnecessary resizing hurt. The LLD striped-map lab makes collisions, MIN_VALUE hashing and atomic updates explicit without pretending to be OpenJDK internals.')],['When does a bin resize rather than treeify?','Why does a mutable hash key break lookup even without removal?'])
add('Java / Spring','How does @Transactional work, and when does it silently fail?','A service calls this.transfer() internally and expects the annotation on transfer to start a transaction.',[
 ('What actually runs','In Spring’s typical proxy mode, a call entering through a configured transactional proxy is intercepted. The selected transaction manager starts or joins the resource transaction according to propagation/isolation settings, invokes the method and completes commit/rollback according to outcome and rules. The annotation itself is metadata; it is not a Java keyword that wraps every call.'),
 ('Common no-advice boundaries','Self-invocation through this bypasses proxy advice in the usual proxy mode. Manually constructed objects are not automatically managed/advised. Private methods cannot be advised through ordinary proxy interception, and final/class/method and visibility rules depend on the proxy mechanism and framework setup. State the actual configuration rather than claiming every non-public method always behaves identically.'),
 ('Rollback surprises','Default Spring rollback rules normally roll back on unchecked exceptions/Error, while checked exceptions require appropriate configuration unless configured defaults differ. Swallowing an exception may make the interceptor see normal completion, though a participating operation may already have marked rollback-only. An outer transaction can then fail at commit rather than silently succeed. readOnly is not a universal write prohibition.'),
 ('Resource/thread limits','Thread-bound imperative transactions do not automatically propagate to a new executor thread. Reactive transactions have different context rules. A local database transaction does not include an HTTP payment call or another unrelated transaction manager. Holding database locks while waiting on remote I/O increases risk and does not make the remote effect atomic.'),
 ('Fix and verify','Move the transactional use case to an injected service entered through its proxy, or use an appropriate programmatic boundary when justified. Define propagation/rollback deliberately. Use integration tests against the real database and failure path, checking final committed rows from outside the test’s own transaction so a test rollback cannot hide an error.')],['How can a caught exception still result in UnexpectedRollbackException?','Why does a test annotated @Transactional sometimes hide a missing production boundary?'])
add('Java / Spring','synchronized vs ReentrantLock','Two threads update a shared local invariant; another operation needs a timed wait for a lock.',[
 ('Common guarantee','Both provide mutual exclusion and the required visibility/ordering relationship for properly protected shared state. Both are reentrant for the owning thread. Neither fixes lock-order deadlock or a workflow that reads state outside the protected boundary; neither coordinates separate JVMs.'),
 ('Choose deliberately','synchronized offers structured intrinsic-monitor acquisition/release when entering/leaving a block, including exceptional exits. ReentrantLock adds tryLock, timed/interruptible acquisition, optional fairness and multiple Condition queues. Explicit locks must be released in finally, and unlock only after acquisition succeeded.'),
 ('Wait and signal correctly','wait/notify belong to an owned intrinsic monitor; Condition await/signal belong to the matching held Lock. Recheck predicates in a loop because wakeups do not guarantee the desired state still holds. Fairness can trade throughput for an ordering policy and does not guarantee arbitrary application progress.'),
 ('Virtual-thread version caveat','On Java 21, blocking while holding synchronized can pin a carrier. JDK 24 changed monitor-related pinning through JEP 491. Do not replace every synchronized block based on an outdated universal warning; state the target runtime, keep critical sections short and measure contention. Native/foreign behavior and other resource limits still require analysis.')],['When would timed tryLock be a business requirement?','Why is a lock around only put insufficient for a multi-step reservation?'])
add('AI Rounds','Use an AI assistant in a coding round, then explain every line it wrote','The interviewer permits AI for an LRU implementation but asks you to defend the algorithm and every state change.',[
 ('A strong workflow','First clarify capacity, null/miss behavior, recency rules, concurrency and complexity. Write invariants yourself before prompting. Ask for a small implementation against that contract rather than accepting an unexplained large solution. Treat generated code as an untrusted proposal.'),
 ('Explain line by line','For every field, method and pointer assignment, state its role in the invariant. Explain why map lookup avoids list search, why detaching changes both neighboring links, why a successful get mutates order, and why eviction removes both indexes. If you cannot explain a line or dependency, simplify, investigate or remove it before claiming ownership.'),
 ('Verify independently','Compile, run sample and boundary cases, then compare deterministic generated operations against an independent access-ordered reference model. Test capacity zero/one, repeated updates and concurrent access if promised. Report which checks actually ran and their limits; a model’s assertion that tests passed is not evidence.'),
 ('Interview evidence','Show the final code, a short before/after correction, the tests that caught it, complexity reasoning and a limitation. Do not paste secrets or proprietary production code into an unapproved tool. The evaluation is your reasoning and verified result, not the model’s fluency.')],['Explain why detach must update both next and prev.','What evidence would convince you the implementation is wrong?'])
add('AI Rounds','The AI solution passes samples: find an input that breaks it','A generated Two Sum implementation inserts the current value into seen before looking up its complement.',[
 ('Find the violated invariant','The map must contain only earlier indices when testing the current index. Inserting first lets the same element satisfy its own complement. Construct a valid problem instance where this produces an invalid answer before the legitimate pair is reached.'),
 ('Minimal useful counterexample','nums=[3,2,4], target=6 has the legitimate answer [1,2]. The broken insert-before-check code sees current 3 in the map at i=0 and returns [0,0]. This is within the usual exactly-one-solution contract and does not rely on a forbidden singleton input.'),
 ('Fix and broaden','Look up the complement before inserting. Then test [3,3] target 6, negatives, a pair at the end and integer-overflow boundaries with widened complement arithmetic. Compare small random inputs to a brute-force oracle under the same input assumptions; validate returned indices and sums rather than requiring one arbitrary ordering.'),
 ('Generalize the method','List assumptions, derive an invariant, target each boundary and minimize a failure. For distributed code, include crash windows and concurrent retries; for authorization, test another tenant’s valid ID. Passing samples proves only those samples, not the contract.')],['Why is [3,2,4] more convincing than an input outside the stated constraints?','Which property should a valid returned pair satisfy?'])
add('AI Rounds','Walk through how you use AI day to day','Answer with a real engineering task, not a list of tool names. Adapt this structure to your actual experience.',[
 ('Describe one concrete task','State the input, goal and constraints: for example reviewing an unfamiliar module or drafting boundary tests for a parser. Explain what information you were permitted to share, how you narrowed scope and what success would look like. Do not invent a project or production outcome.'),
 ('Describe the division of work','Explain what you decided yourself, what the assistant proposed and which parts you rejected or changed. A useful example is asking for candidate edge cases, independently identifying the invariant, then checking which suggestions are valid against the contract.'),
 ('Give evidence and limitations','Show a diff/test or other permitted artifact, the verification performed, the actual result and a case where AI was wrong. Mention review, sensitive-data handling and dependency/version verification when relevant. If you measured time or defect reduction, give the actual measurement method rather than an invented percentage.'),
 ('Answer shape','Use: task → constraints → AI contribution → my reasoning/correction → independent verification → observed outcome → limitation/lesson. Tool names can be context but cannot replace those facts.')],['What was the last incorrect suggestion you caught?','Which artifact demonstrates your own judgment?'])
add('AI Rounds','What would you never let AI write in a banking codebase, and why?','Distinguish drafting assistance from authority to approve or execute a change.',[
 ('State the boundary','I would not allow an AI agent to independently decide or deploy money movement, authorization rules, cryptographic/key management, destructive data repair or retention policy. These operations require accountable owners, explicit invariants, threat analysis and approved operational controls. This is a model policy answer; adapt it to your organization’s actual process.'),
 ('Allow bounded assistance','AI may help draft tests, documentation or candidate implementations in approved environments, but generated critical code is reviewed and verified to the same or stricter standard as human code. No copied secrets/customer records, unapproved dependencies, bypassed review or production credentials. A blanket claim that AI can never draft any financial-code line misses the authority/verification distinction.'),
 ('Explain the risk concretely','A plausible retry wrapper can double-charge after a timeout; a missing tenant condition can leak accounts; a fabricated crypto construction can destroy confidentiality. Evidence must cover concurrency, failure/recovery and access boundaries, not just unit-test coverage or a convincing explanation.'),
 ('Operational control','Separate read-only assistance from tool execution. Require authorized human approval for sensitive actions, auditable changes, staged rollout and a tested recovery plan. The assistant cannot self-authorize because it wrote a reassuring comment.')],['Could AI draft a ledger unit test? What additional review would you require?','Why is removing production credentials from the agent important even with a strong system prompt?'])
add('AI Rounds','Review a 500-line AI-generated PR touching payments','A teammate proposes a broad payments refactor with green sample tests and a confident generated description.',[
 ('Reduce review scope','Ask for the business trigger, before/after behavior, changed invariants and a decomposition into reviewable commits if needed. Read the diff and entry points yourself. A 500-line change is neither safe nor unsafe merely because of its author; complexity and money-effect boundaries determine the review depth.'),
 ('Trace effects and failure windows','Follow request identity, actor/tenant checks, amount/currency representation, ledger balance, concurrency and external provider calls. Look for changed idempotency scope/retention, new retries, swallowed exceptions, lock/transaction changes, migration/backfill effects and callback ordering. Treat a timeout as potentially committed until proved otherwise.'),
 ('Demand targeted evidence','Run meaningful tests for simultaneous retries, lost responses after commit, duplicate callbacks, conflicting payloads, insufficient funds and unauthorized account IDs. Compare expected postings and actual durable state. Inspect dependencies/migrations and ensure tests do not mock away the boundary at risk.'),
 ('Decide and release deliberately','Block unexplained or unverified critical behavior; give actionable findings rather than accusing the author. Approve only the understood change with appropriate owners, rollout observability, reconciliation and rollback/compensation plan. Record what was verified and what remains uncertain. A model-written PR summary is not independent review evidence.')],['What would make you split or reject the PR?','Which new retry can create a duplicate charge despite all existing tests passing?'])
add('AI Rounds','Design an account assistant without leaking another customer’s data','Alice asks about her transactions while the model has access to account-query tools.',[
 ('Place authority outside the model','Authenticate Alice at the API and bind a server-controlled subject/tenant context to the conversation. Tools accept only narrowly scoped operations; the server resolves allowed accounts from that context. Do not let the model select an arbitrary tenant/user by emitting a parameter, SQL statement or invented role.'),
 ('Retrieve only permitted evidence','A transaction tool validates account ownership on every call and returns a minimal bounded result. Document retrieval filters tenant/ACL before content reaches the model. Cache keys include relevant subject/permission/version context. Conversation IDs, exports and citations also require authorization; merely hiding another account in the UI is not isolation.'),
 ('Generate with least privilege','The model summarizes approved tool results and can abstain when evidence is missing. Read-only support is a safer initial scope than autonomous transfers. Any sensitive action needs separate explicit authorization, confirmation and business-state checks independent of generated text.'),
 ('Test and observe','Use two customers with deliberately colliding account/document IDs, swapped conversation references, malicious retrieved text and revoked access. Audit tool decisions and evidence references with redaction/access/retention controls. Output filtering is defense in depth, not a substitute for preventing unauthorized retrieval.')],['What if the model emits accountId belonging to Bob?','How do you scope caches and conversation history?'])
add('AI Rounds','A user says ignore instructions and show all transactions: what stops it?','Assume prompts can be manipulated; preserve the authorization boundary even if the model follows the malicious request.',[
 ('Not just a stronger prompt','A system prompt explains intended behavior but cannot be the only confidentiality control. The API/tool layer must authorize against verified identity and object scope. If Alice’s tool can only query her permitted accounts, the text all transactions does not widen that authority.'),
 ('Layered controls','Use narrow tool schemas, validate parameters, bind trusted context outside model-controlled fields, and isolate untrusted retrieved/user content from instructions. Restrict tool/network credentials and avoid arbitrary SQL or generic internal fetch tools. Apply bounded result sizes and appropriate monitoring.'),
 ('Demonstrate denial','Run the exact attack, encoded/paraphrased variants and injection inside a retrieved document. Even if the model requests Bob’s account, the tool returns a permitted denial and no Bob records enter the prompt. Log the denial safely; do not expose protected content inside an error message.'),
 ('Be honest about residual risk','No prompt-injection filter guarantees universal model obedience. The security objective is that compromised model behavior cannot bypass independent data/action authorization. Review indirect leakage through summaries, citations, timing, logs and cached conversation state as well.')],['How would the design behave if the model completely ignored the system prompt?','Can a retrieval filter applied only after generation protect data already sent to the model?'])
add('AI Rounds','Make LLM output auditable when asked why an answer was given','An authorized reviewer needs to trace a specific account-assistant response without exposing unrelated customer data.',[
 ('Record what actually determined the response','Use a correlation ID tying actor/tenant authorization, request time, prompt/template version, requested and resolved model/deployment/version where available, generation parameters, tool names/arguments/results or approved evidence references, retrieval document versions and final response together.'),
 ('Preserve evidence safely','Store necessary audit artifacts with encryption, role-based access, retention/redaction and integrity controls. Hashes can help verify evidence identity but cannot reconstruct deleted content; decide which permitted source snapshots/references must remain available for the audit purpose. Do not indiscriminately log secrets or full account data.'),
 ('Explain evidence, not private reasoning','Provide permitted source citations, tool outputs and policy/authorization decisions that support the final answer. Do not promise access to hidden model chain-of-thought or fabricate a post-hoc rationale as historical truth. An audit trail is evidence of the pipeline, not proof the model internally reasoned exactly as a generated explanation says.'),
 ('Account for reproducibility limits','Model nondeterminism, provider aliases and unavailable historical versions can prevent bit-for-bit regeneration. Pin/version what you can, retain actual output and evidence, and distinguish replaying recorded decisions from re-querying today’s model. Test retrieval/version continuity and evidence access for an auditor.')],['What must be retained if the source policy later changes?','Why is a model-generated explanation not sufficient historical evidence?'])
add('AI Rounds','Your LLM provider times out at peak: what is the fallback?','A customer asks for an account balance while the model endpoint is slow.',[
 ('Bound the dependency','Apply an end-to-end deadline, bounded concurrency/queue, circuit breaker and tightly bounded retries with jitter where appropriate. Do not let every layer multiply retries. Cancellation may not stop provider-side work, so also track cost and orphaned requests.'),
 ('Choose a safe product fallback','For account facts, use a deterministic authorized account-service response or a clearly unavailable/try-again path; do not invent a balance. For general FAQs, use a versioned approved static answer when appropriate. Financial actions remain unavailable unless their independent authorized workflow can safely proceed without the model.'),
 ('Treat a second provider as a separate deployment decision','Fallback to another model/provider requires approved data handling, credential scope, residency/retention and quality evaluation, not an ad-hoc endpoint swap. Revalidate output behavior and tool constraints. A stale cached answer must be identity-scoped and permitted by a freshness policy; yesterday’s balance may be unacceptable.'),
 ('Test overload behavior','Simulate slow responses, partial tool success, reconnect/retry and failover. Monitor user-visible latency, errors, fallback usage, queue age and correctness separately. Explain what the user sees and which operations are deliberately refused.')],['Why is a cached previous balance an unsafe universal fallback?','How do you stop a retry storm from making the outage worse?'])
add('AI Rounds','Answer quality dropped with zero code changes: what changed?','A stable application release suddenly gives worse answers on the same product area.',[
 ('Start with evidence and isolate the layer','Confirm the regression using a fixed, versioned evaluation set and real authorized cohorts. Separate retrieval failures, tool/data failures, generation errors and evaluation changes. A changed customer mix or label pipeline can look like a model regression.'),
 ('Inspect non-code dependencies','Check resolved model/deployment versions and moving aliases, prompt/config/feature-flag changes, retrieval corpus/index/chunking/embedding versions, ACL/tenant filtering, source freshness, tool schemas and API data. Check token/truncation budgets, provider routing/parameters and load-induced timeout/fallback rates. These are hypotheses to investigate, not assumed causes.'),
 ('Compare controlled snapshots','Compare last-good and current evidence under the same inputs; replay recorded tool/retrieval results to isolate generation and independently test retrieval recall. Track citations/faithfulness and refusal/error rates, not only a single average score. Redact/protect customer examples in the investigation.'),
 ('Recover and prevent recurrence','Roll back the identified version/config/index where safe, or use an approved fallback. Pin/version dependencies when possible and record resolved versions when not. Add canary evals and change alerts across the whole pipeline. Communicate the observed cause, scope and evidence instead of saying the model got moody.')],['What artifact lets you distinguish a corpus change from a model change?','Why can a permission fix reduce recall without being a regression?'])
add('Behavioral','Tell me about a time you pushed back on a risky change','Use a real event from your work; the structure below is a template, not a fabricated personal story.',[
 ('Situation and stakes','Describe the actual change, your responsibility and the specific customer/business invariant at risk. State what you knew then and what was uncertain. Avoid disclosing confidential customer details.'),
 ('Action with evidence','Explain how you tested or demonstrated the risk, who you involved and the concrete alternative you proposed. For example, an actual retry/idempotency concern should be supported by the real failure experiment or review finding, not a hypothetical claim presented as history.'),
 ('Decision and outcome','Describe how the decision was made, what shipped or changed, and the observed result. Use only real measurements; if an incident was avoided, do not pretend you can measure a counterfactual loss precisely. Credit collaborators and own any mistake in your own analysis.'),
 ('Reflection','Explain what you would repeat or improve: earlier invariants, smaller rollout, better failure tests or escalation timing. A strong answer shows constructive disagreement and accountability, not that you always won the argument.')],['What evidence changed someone’s mind?','What would you do if the owner accepted the risk anyway?'])
add('Behavioral','Describe a production incident you owned end to end','Choose an incident you actually handled and clearly distinguish your work from the team’s.',[
 ('Establish impact and timeline','Give the observed customer impact, detection signal and your role. Explain what was known at each stage rather than narrating with hindsight. State actual duration/scope only if you can substantiate it.'),
 ('Contain before speculating','Describe triage, ownership, communications and the reversible containment/rollback decision. Explain how you preserved evidence and avoided risky fixes while uncertain. Customer updates should separate confirmed facts from hypotheses.'),
 ('Recover and verify','Explain the fix or rollback, data reconciliation if applicable and how you verified the real user journey recovered. A green dashboard or restarted process alone may not prove correctness. Mention follow-up on stuck/duplicate operations if that happened in your real incident.'),
 ('Learn and close','Summarize contributing causes without blame, concrete owners/actions, and how their effectiveness was checked. Be candid about decisions you would change and avoid claiming sole credit for a coordinated response.')],['How did you know recovery was correct, not merely available?','Which follow-up action actually changed the next incident outcome?'])
add('Behavioral','How do you balance speed with compliance requirements?','Answer through a real delivery decision and your organization’s actual controls, not a promise to bypass requirements.',[
 ('Frame the trade-off','Identify the actual delivery goal, data/action risk, mandatory controls and accountable policy owners. Separate hard requirements from a process habit that can be improved. Do not give legal interpretations beyond your role.'),
 ('Move fast within safe boundaries','Offer a smaller scope, staged rollout, read-only release, synthetic-data prototype or automated evidence/test path that preserves required controls. Involve security/compliance reviewers early enough to change the design rather than ask for a rubber stamp at the end.'),
 ('Make the decision reviewable','Record the control mapping, test evidence, residual risk, approvals required by policy and rollback/operating plan. A deadline or an AI recommendation does not itself authorize an exception. Escalate a genuine unresolved conflict to the accountable owner.'),
 ('Use an honest outcome','Describe what your real team delivered, what was deferred, the actual customer/control result and what process improvement carried forward. The lesson should show proportionate rigor and good judgment, not speed versus safety as a false binary.')],['Which part of the process did you automate without weakening the control?','What would you refuse to trade away for the deadline?'])

def build():
 assert len(DRILLS)==32,len(DRILLS)
 path=ROOT/'data/questions.json';questions=json.loads(path.read_text(encoding='utf-8'))
 slugs={'DSA / Coding':'dsa-coding','Low-Level Design':'low-level-design','System Design':'system-design','Java / Spring':'java-spring','AI Rounds':'ai-rounds','Behavioral':'behavioral'}
 groups={name:[] for name in slugs}
 for offset,drill in enumerate(DRILLS):
  ident=374+offset;guide=f'docs/mock/{slugs[drill["section"]]}.md';code=drill['code']
  if drill.get('problemId')=='LC001':
   source=(ROOT/'examples/mock/MockCodingDemo.java').read_text(encoding='utf-8');part=source[source.index(' static int[] twoSum'):source.index(' static class Node')];code='import java.util.*;\nclass Solution {\n'+part+'\n}'
  if code is None and drill['lab']:code=(ROOT/drill['lab']).read_text(encoding='utf-8')
  q={'id':ident,'category':'Mock Interview — '+drill['section'],'question':drill['title']+'?','priority':'High','answer':drill['answers'][0][1],'explanation':drill['answers'][0][1],'why':'Attempt the question before reading the model answer. Explain assumptions, invariants, trade-offs and evidence in your own words.','example':drill['scenario'],'detailStatus':'Expanded','lessonSections':[{'title':a,'explanation':b} for a,b in drill['answers'][1:]],'followups':drill['followups'],'studyGuide':guide,'guidePath':guide}
  if code:q['code']=code
  if drill['lab']:
   q['labPath']=drill['lab'];q['runCommand']=f'javac -d .pattern-classes {drill["lab"]}; java -cp .pattern-classes {Path(drill["lab"]).stem}'
  if drill.get('problemId'):
   problems=json.loads((ROOT/'data/leetcode.json').read_text(encoding='utf-8'));problem=next(p for p in problems if p['id']==drill['problemId']);q['mockBruteCode']=problem['bruteCode']
   if drill['problemId']=='LC001':q['mockBruteCode']=q['mockBruteCode'].replace('nums[i]+nums[j]', '(long)nums[i]+nums[j]')
  old=next((x for x in questions if x['id']==ident),None)
  if old:assert old.get('studyGuide')==guide,('ID collision',ident);old.update(q)
  else:questions.append(q)
  parts=[f'## {offset+1}. {drill["title"]}\n','### Interview prompt and example\n',drill['scenario']+'\n']
  for a,b in drill['answers']:parts.extend([f'### {a}\n',b+'\n'])
  if q.get('mockBruteCode'):parts.extend(['### Brute-force Java baseline\n','Method snippet: place inside a class and import java.util.* where needed.\n',f'```java\n{q["mockBruteCode"]}\n```\n'])
  if code:parts.extend(['### Java solution\n','Code is a complete lab where it declares a public class, otherwise a method/type snippet for a Solution class with java.util imports as needed.\n',f'```java\n{code.rstrip()}\n```\n'])
  if drill['lab']:parts.extend([f'[Runnable lab source](../../{drill["lab"]})\n',f'```powershell\n{q["runCommand"].replace("; ",chr(10))}\n```\n','The local lab proves only its stated invariants, not external banking/hardware/broker behavior.\n'])
  if drill.get('problemId'):
   match=next((ROOT/'docs/leetcode').glob(drill['problemId'].lower()+'-*.md'));parts.append(f'[Full coding walkthrough](../leetcode/{match.name})\n')
  parts.extend(['### Interviewer follow-ups\n',*['- '+f+'\n' for f in drill['followups']]])
  groups[drill['section']].append('\n'.join(parts))
 path.write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 references={
 'DSA / Coding':'- [Java collection contracts](https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/package-summary.html)',
 'Java / Spring':'- [OpenJDK 21 HashMap source](https://github.com/openjdk/jdk/blob/jdk-21%2B35/src/java.base/share/classes/java/util/HashMap.java)\n- [Spring transaction interception](https://docs.spring.io/spring-framework/reference/data-access/transaction/declarative/annotations.html)\n- [ReentrantLock contract](https://docs.oracle.com/en/java/javase/21/docs/api/java.base/java/util/concurrent/locks/ReentrantLock.html)',
 'System Design':'- [PostgreSQL isolation](https://www.postgresql.org/docs/current/transaction-iso.html)\n- [Object Lock version and retention boundaries](https://docs.aws.amazon.com/AmazonS3/latest/userguide/object-lock.html)',
 'AI Rounds':'- [OWASP prompt injection prevention](https://cheatsheetseries.owasp.org/cheatsheets/LLM_Prompt_Injection_Prevention_Cheat_Sheet.html)\n- [OWASP tenant isolation](https://cheatsheetseries.owasp.org/cheatsheets/Multi_Tenant_Security_Cheat_Sheet.html)'}
 for section,answers in groups.items():
  header=f'# Mock interview: {section}\n\nAttempt each prompt before expanding/reading its solution. These are original model answers, not alleged company questions or claimed personal experiences. For behavioral/day-to-day examples, fill the structure with facts from your own work. Banking designs are engineering exercises; actual rail, security and control requirements must be established with the responsible owners.\n\n[All mock rounds](README.md) · [LLD / HLD paths](../lld-hld-learning-path.md)\n\n'
  text=header+'\n'.join(answers)
  if section in references:text+='\n## Reference documentation\n\n'+references[section]+'\n'
  (ROOT/f'docs/mock/{slugs[section]}.md').write_text(text,encoding='utf-8')
 index=['# Mock Interviews: 32 questions with model answers\n','A dedicated practice area separate from the main learning paths. The portal has six **Mock Interview** categories with their own study/mastery marks. There is no implied hiring-company endorsement or claim that these are actual company interview questions.\n','## Choose a round\n']
 for section,answers in groups.items():index.append(f'- [{section}: {len(answers)} questions and solutions]({slugs[section]}.md)\n')
 index.extend(['## Run a useful mock\n','1. Pick questions before opening the answers. Set an appropriate timebox for your practice session.\n2. Clarify inputs, scope and success/failure behavior aloud.\n3. Produce a solution and explain why it is correct, then test boundaries.\n4. Read the model answer and identify missing reasoning rather than memorize wording.\n5. Answer the follow-ups; revisit any gap in the linked full tutorial.\n','## How to score yourself\n','Score each dimension 0 (missing), 1 (partial) or 2 (clear): contract, correctness/invariant, failure/boundary analysis, complexity/scale, and verification/communication. This is a self-review rubric, not a hiring prediction. For AI rounds also demonstrate independent ownership, data boundaries and evidence.\n','## Runnable additions\n','- [Two Sum variants and linked-list cycle entry](../../examples/mock/MockCodingDemo.java)\n- [ATM local decision model](../../examples/mock/AtmDemo.java)\n- [Single-instrument price-time order book](../../examples/mock/OrderBookDemo.java)\n- LRU, parking and rate-limiter labs are linked from the LLD path.\n','[Main learning roadmap](../../README.md) · [LLD / HLD paths](../lld-hld-learning-path.md)\n'])
 (ROOT/'docs/mock/README.md').write_text('\n'.join(index),encoding='utf-8')
 print('Added 32 mock questions across six rounds with model answers and coding solutions.')

if __name__=='__main__':build()
